def _coloring_for(apps, part_id, material_id, cache):
    """Расцветка «первая позиция из этого материала, остальные по умолчанию»."""
    PartMaterial = apps.get_model("production", "PartMaterial")
    PartColoring = apps.get_model("production", "PartColoring")
    PartColoringItem = apps.get_model("production", "PartColoringItem")
    Material = apps.get_model("catalog", "Material")
    if (part_id, material_id) in cache:
        return cache[(part_id, material_id)]
    positions = list(PartMaterial.objects.filter(part_id=part_id).order_by("order", "pk"))
    if not positions:
        return None
    materials = {p.pk: p.material_id for p in positions}
    materials[positions[0].pk] = material_id or positions[0].material_id
    key = ";".join(f"{p.pk}:{materials[p.pk]}" for p in positions)
    label_parts = []
    for p in positions:
        m = Material.objects.select_related("color").get(pk=materials[p.pk])
        name = f"{m.name}, {m.color.name.lower()}" if m.color_id else m.name
        label_parts.append(f"{p.name}: {name}" if p.name else name)
    coloring, created = PartColoring.objects.get_or_create(
        part_id=part_id, key=key, defaults={"label": " + ".join(label_parts)}
    )
    if created:
        PartColoringItem.objects.bulk_create(
            [
                PartColoringItem(coloring=coloring, position=p, material_id=materials[p.pk])
                for p in positions
            ]
        )
    cache[(part_id, material_id)] = coloring
    return coloring


def move_to_colorings(apps, schema_editor):
    """Материал детали в строках и остатках → расцветка; материал выпуска → строка выпуска."""
    cache = {}
    for label in (
        "StockMove",
        "StockBalance",
        "TransferLine",
        "InventoryLine",
        "ReceivingLine",
        "WriteOffLine",
    ):
        Model = apps.get_model("stock", label)
        for row in Model.objects.filter(part__isnull=False):
            coloring = _coloring_for(apps, row.part_id, row.part_material_id, cache)
            if coloring is not None:
                row.part_coloring_id = coloring.pk
                row.save(update_fields=["part_coloring"])
    ProductionRun = apps.get_model("stock", "ProductionRun")
    ProductionRunMaterial = apps.get_model("stock", "ProductionRunMaterial")
    PartMaterial = apps.get_model("production", "PartMaterial")
    for run in ProductionRun.objects.all():
        main = PartMaterial.objects.filter(part_id=run.part_id).order_by("order", "pk").first()
        if main is not None:
            ProductionRunMaterial.objects.get_or_create(
                run=run,
                position=main,
                defaults={"material_id": run.material_id or main.material_id},
            )


